// (Q25, notas-dev/xr.md) The descriptions of what Q25 shows in the editor: Project Settings > VR, VR Preview, Package
// for Meta Quest, the Interactable's VR options and the Virtual Reality template (a file of its own so the branches don't collide).
#include "ui_tips.h"

#define T(label, en, pt) { label, { en, pt } }

const UiTip g_ui_tips_q25[] = {
    T("Start in VR", "The packaged game opens on the VR headset (OpenXR): Quest Link, Air Link, SteamVR on a PC, the Quest by itself in its APK. No headset connected: it plays on the monitor as always.", "O jogo empacotado abre no headset de VR (OpenXR): Quest Link, Air Link, SteamVR no PC, o Quest sozinho no APK dele. Sem headset conectado: roda no monitor como sempre."),
    T("PC VR (OpenXR)", "The game for PC headsets through the active OpenXR runtime (Meta Horizon Link for a Quest by cable or Air Link, SteamVR): no SDK needed.", "O jogo para headsets de PC pelo runtime OpenXR ativo (Meta Horizon Link para um Quest por cabo ou Air Link, SteamVR): sem SDK."),
    T("Meta Quest (standalone)", "The game running inside the Quest itself, no PC: Build > Package for Meta Quest makes its APK (the OpenXR loader and Meta's VR manifest in it).", "O jogo rodando dentro do próprio Quest, sem PC: Compilar > Empacotar para Meta Quest gera o APK (com o loader OpenXR e o manifesto VR da Meta)."),
    T("Refresh Rate", "The headset's display rate asked at the start: 72, 90 or 120 Hz on a Quest (the game must draw both eyes in 13.9, 11.1 or 8.3 ms). Headset's Own keeps its setting.", "A taxa da tela do headset pedida no início: 72, 90 ou 120 Hz num Quest (o jogo precisa desenhar os dois olhos em 13,9, 11,1 ou 8,3 ms). A do Headset mantém o ajuste dele."),
    T("Tracking Space", "Floor: the play space's origin on the real floor, the player standing and walking around the room (the guardian's middle). Seated: the head's height set by Seated Eye Height, for cockpits and seated games.", "Chão: a origem do espaço de jogo no chão real, o jogador em pé andando pelo quarto (o meio do guardião). Sentado: a altura da cabeça dada pela Altura dos Olhos Sentado, para cabines e jogos sentados."),
    T("Seated Eye Height", "Where a seated player's eyes are above the floor of the level (cm).", "Onde ficam os olhos do jogador sentado acima do chão do nível (cm)."),
    T("Locomotion", "How the VR player crosses the level: Teleport (the left stick pushed shows an arc, released goes there: the most comfortable), Smooth (the left stick walks where the head looks), or both.", "Como o jogador de VR atravessa o nível: Teleporte (o analógico esquerdo empurrado mostra um arco, solto vai até lá: o mais confortável), Suave (o analógico esquerdo anda para onde a cabeça olha), ou os dois."),
    T("Turning", "How the right stick turns the player: Snap Turn (a jump of some degrees around the head: comfortable), Smooth Turn, or none (the player turns in the room).", "Como o analógico direito gira o jogador: Giro por Passos (um salto de alguns graus em volta da cabeça: confortável), Giro Suave, ou nenhum (o jogador gira no quarto)."),
    T("Snap Turn Angle", "Degrees of each snap turn.", "Graus de cada giro por passos (45)."),
    T("Turn Speed", "Degrees a second of the smooth turn at the stick's full push.", "Graus por segundo do giro suave com o analógico todo empurrado."),
    T("Move Speed", "The smooth walk's speed (cm/s); a Character moves at most its Max Walk Speed.", "A velocidade do andar suave (cm/s); um Character anda no máximo na Max Walk Speed dele."),
    T("Teleport Range", "How far the teleport's arc reaches on flat ground (cm).", "Até onde o arco do teleporte chega em chão plano (cm)."),
    T("Comfort Vignette", "Darkens the edge of the view while moving or turning smoothly, a pulse on a snap turn or a teleport: the eyes see less motion, the player feels less sick. 0 turns it off.", "Escurece a borda da visão enquanto anda ou gira suave, um pulso no giro por passos ou no teleporte: os olhos veem menos movimento, o jogador enjoa menos. 0 desliga."),
    T("Show Hands", "Draws the player's hands where the controllers are, the fingers closing with the trigger and the grip (tracked hands: as they really are). Hide them to draw your own by Get Motion Controller Pose.", "Desenha as mãos do jogador onde estão os controles, os dedos fechando com o gatilho e o grip (mãos rastreadas: como elas estão). Esconda para desenhar as suas com Get Motion Controller Pose."),
    T("Hand Tracking", "Uses the headset's cameras to follow bare hands (the Quest's hand tracking): a pinch is the trigger, a fist the grip, the index aims the laser.", "Usa as câmeras do headset para seguir as mãos sem controle (o hand tracking do Quest): a pinça é o gatilho, o punho fechado o grip, o indicador aponta o laser."),
    T("Laser Pointer", "A ray from the hand: it points at menus (the trigger clicks) and at Interactables (the trigger uses doors, levers, buttons).", "Um raio saindo da mão: aponta para menus (o gatilho clica) e para Interagíveis (o gatilho usa portas, alavancas, botões)."),
    T("Drag to Move", "Close a hand in the air (a fist with tracked hands, the grip with a controller) where there is nothing to grab: it holds the world and the player pulls along, like climbing along the floor; both hands pull together, let go for a short glide. The walls stop it.", "Feche a mão no ar (o punho com as mãos rastreadas, o grip com um controle) onde não há nada para pegar: ela segura o mundo e o jogador se puxa, como escalar pelo chão; as duas mãos puxam juntas, solte para um pequeno deslize. As paredes param."),
    T("Teleport Fade", "A blink to black at each teleport, its seconds (0: none): the eyes don't see the jump, the most comfortable for most players.", "Uma piscada para o preto a cada teleporte, em segundos (0: nenhuma): os olhos não veem o salto, o mais confortável para a maioria."),
    T("Blink on Snap Turn", "A short blink at each snap turn (the same as the teleport's): the turn not seen.", "Uma piscada curta a cada giro por passos (a mesma do teleporte): o giro não é visto."),
    T("Dominant Hand", "The player's main hand: its stick turns and its laser points; the other hand's stick teleports or walks. Left: for the left-handed.", "A mão principal do jogador: o analógico dela gira e o laser dela aponta; o analógico da outra teleporta ou anda. Esquerda: para os canhotos."),
    T("Smooth Move Direction", "Where the smooth walk goes: where the head looks, or where the moving hand points (look around while walking straight).", "Para onde vai o andar suave: para onde a cabeça olha, ou para onde a mão que anda aponta (olhar em volta andando reto)."),
    T("Physical Hands", "The drawn hands stop at walls, floors and tables instead of going through them (the real hand may go on: the drawn one waits at the surface).", "As mãos desenhadas param em paredes, chão e mesas em vez de atravessar (a mão real pode seguir: a desenhada espera na superfície)."),
    T("Hands Push Bodies", "A hand touching a body with physics pushes it: as deep as the real hand goes in (an open hand laid on it slowly too), or at the hand's speed when it hits it; knock over cans, roll a ball, without grabbing. A hand closing on a Grabbable doesn't shove it. Set VR Hand Collision changes it in game.", "Uma mão encostando num corpo com física o empurra: o quanto a mão real entra nele (a mão aberta pousada devagar também), ou na velocidade da mão quando bate; derrubar latas, rolar uma bola, sem pegar. A mão fechando num Pegável não o empurra. Set VR Hand Collision muda isso em jogo."),
    T("Held Objects Collide", "What a hand holds stops at walls and tables too (a sword doesn't go through the wall).", "O que a mão segura também para em paredes e mesas (uma espada não atravessa a parede)."),
    T("Head in Walls", "When the player's real head goes into a wall: Fade to Black (Meta's advice: the view darkens until the head comes out), Push Back (the player moved so the head stays outside) or Off.", "Quando a cabeça real do jogador entra numa parede: Escurecer (o conselho da Meta: a vista escurece até a cabeça sair), Empurrar (o jogador é movido para a cabeça ficar fora) ou Desligado."),
    T("Hide the Pawn's Body", "In VR the pawn's own meshes (its body, a mannequin, its capsule's cylinder) are hidden: the eyes are inside them. Only the hands are seen.", "Em VR as malhas do próprio pawn (o corpo, um manequim, o cilindro da cápsula) ficam escondidas: os olhos estão dentro delas. Só as mãos aparecem."),
    T("Grab Reach", "How far from the hand (cm) a Grabbable is taken by the grip or the fist.", "A que distância da mão (cm) um Pegável é pego pelo grip ou pelo punho."),
    T("Distance Grab", "The grip on a Grabbable the laser points at pulls it into the hand, from across the room.", "O grip num Pegável que o laser aponta o puxa para a mão, do outro lado da sala."),
    T("Throw Strength", "The throw's speed times this: 1 as the hand moved; above it, throws go farther (an arcade feel).", "A velocidade do arremesso vezes isto: 1 como a mão se moveu; acima, os arremessos vão mais longe (um jeito arcade)."),
    T("Haptics", "The controllers' vibrations' strength (grab, teleport, click, touch); 0 turns them off.", "A força das vibrações dos controles (pegar, teleportar, clicar, tocar); 0 desliga."),
    T("Laser Length", "How far the laser reaches (cm): widgets, Interactables and distance grabs beyond it are not pointed at.", "Até onde o laser alcança (cm): widgets, Interagíveis e pegadas a distância além disso não são apontados."),
    T("Menu Distance", "How far before the head the menu panel opens (cm).", "A que distância à frente da cabeça o painel de menu abre (cm)."),
    T("Menu Width", "The menu panel's width (cm); its height follows the UI's shape.", "A largura do painel de menu (cm); a altura segue o formato da UI."),
    T("Left Hand Mesh", "A Static Mesh or a Skeletal Mesh (its bones named as OpenXR's joints: the fingers move) of the Content drawn as the left hand (empty: the engine's hands). Its forward along the fingers, its up the back of the hand.", "Uma Static Mesh ou Skeletal Mesh (ossos com os nomes das juntas do OpenXR: os dedos mexem) do Content desenhada como a mão esquerda (vazio: as mãos da engine). A frente dela ao longo dos dedos, o topo nas costas da mão."),
    T("Right Hand Mesh", "A Static Mesh or a Skeletal Mesh of the Content drawn as the right hand (empty: the engine's hands). A Skeletal Mesh with OpenXR's joint names on its bones moves its fingers.", "Uma Static Mesh ou Skeletal Mesh do Content desenhada como a mão direita (vazio: as mãos da engine). Uma Skeletal Mesh com os nomes das juntas do OpenXR nos ossos mexe os dedos."),
    T("Export Base Hand (FBX)...", "Writes the base hand (both sides, OpenXR's 26 bones, 7 poses, a read-me) to a folder: the start for a modeler and a rigger.", "Grava a mão base (as duas, os 26 ossos do OpenXR, 7 poses, um leia-me) numa pasta: o ponto de partida de um modelador e de um rigger."),
    T("Use the Base Hand", "Imports the base hand into /Content/VR/Hands and sets it as the VR hands, its fingers moved by the tracked joints or the controller.", "Importa a mão base para /Content/VR/Hands e a usa como mão do VR, os dedos movidos pelas juntas rastreadas ou pelo controle."),
    T("Hand Mesh Scale", "The hand meshes' scale (1: as modeled).", "A escala das malhas das mãos (1: como foram modeladas)."),
    T("Hand Mesh Rotation", "The hand meshes' rotation in the hand (pitch, yaw, roll, degrees): to match a mesh modeled another way.", "A rotação das malhas das mãos na mão (pitch, yaw, roll, graus): para casar com uma malha modelada de outro jeito."),
    T("VR MSAA", "The VR view's multisampling (1, 2, 4, 8): VR's anti-aliasing (no screen history between the eyes). 4 on a Quest: its GPU resolves it on the chip.", "O multisampling da vista em VR (1, 2, 4, 8): o anti-aliasing do VR (sem histórico de tela entre os olhos). 4 num Quest: a GPU dele resolve no chip."),
    T("Headroom Target", "The frame rate the GPU's two eyes are kept able to reach, above the display's: 150 at 120 Hz keeps them in 6.7 ms, room for a heavier moment (an explosion, many characters) without a dropped frame. Dynamic Foveation shades the edges coarser before the time runs out. 0: the display's own.", "A taxa que os dois olhos na GPU precisam conseguir atingir, acima da do display: 150 a 120 Hz os mantém em 6,7 ms, folga para um momento mais pesado (uma explosão, muitos personagens) sem perder quadro. A Foveação Dinâmica sombreia as bordas mais grosso antes de faltar tempo. 0: a do próprio display."),
    T("Safety Net", "The pawn fallen out of the level (5 m under where it last stood) or falling for 2 s is put back on the last ground it stood on, with a blink: a VR player never lost in the void (a hole, a thin floor, a drag into a table).", "O pawn que cai para fora do nível (5 m abaixo de onde estava) ou fica caindo 2 s volta ao último chão onde estava, com uma piscada: o jogador de VR nunca se perde no vazio (um buraco, um chão fino, um arrasto contra uma mesa)."),
    T("Window Mirror", "What the PC's window shows while playing in VR, the one a recording or a stream takes: Both Eyes (as the headset, side by side), One Eye (the dominant eye's middle filling the window: no cost), Spectator Camera (a steady view following the head, its own field of view: one more view drawn each frame, PC only).", "O que a janela do PC mostra jogando em VR, a que uma gravação ou transmissão pega: Os Dois Olhos (como o headset, lado a lado), Um Olho (o meio do olho dominante preenchendo a janela: sem custo), Câmera do Espectador (uma vista estável seguindo a cabeça, com FOV próprio: uma vista a mais por quadro, só no PC)."),
    T("Spectator FOV", "Degrees across the Spectator Camera's view (wider than a TV game's: the headset sees ~100).", "Graus de largura da vista da Câmera do Espectador (mais larga que a de um jogo de TV: o headset vê ~100)."),
    T("Spectator Smoothing", "How slowly the Spectator Camera follows the head: 0 as the head moves, near 1 very steady (the small shakes of a head never reach the recording).", "O quanto a Câmera do Espectador segue a cabeça devagar: 0 como a cabeça se move, perto de 1 bem estável (os tremores pequenos da cabeça não chegam à gravação)."),
    T("Hands Collide with Objects", "With Physical Hands on: the drawn hands stop at bodies with physics and Interactables (doors, levers, Grabbables) too, the fingers included. Off: only walls, floors and tables stop them; they pass through what moves. Set VR Hand Collision changes it in game.", "Com Mãos Físicas ligado: as mãos desenhadas param também em corpos com física e Interagíveis (portas, alavancas, Pegáveis), os dedos inclusive. Desligado: só paredes, chão e mesas as param; elas atravessam o que se move. Set VR Hand Collision muda isso em jogo."),
    T("Grab Gesture", "What a tracked hand (no controller) does to grab: a Fist; a Pinch (the thumb on the index); Any Finger to Index (the thumb or the middle finger on the index: a pinch with any finger); or a Fist or Any Finger to Index (the default). A controller always grabs with its grip.", "O que uma mão rastreada (sem controle) faz para pegar: Punho; Pinça (o polegar no indicador); Qualquer Dedo no Indicador (o polegar ou o médio no indicador: uma pinça com qualquer dedo); ou Punho ou Qualquer Dedo no Indicador (o padrão). Um controle sempre pega com o grip."),
    T("Drag Gesture", "What a tracked hand does in the air to hold the world and drag the player (Drag to Move): the same choices as Grab Gesture; a Fist by default.", "O que uma mão rastreada faz no ar para segurar o mundo e arrastar o jogador (Arrastar para Andar): as mesmas escolhas do Gesto de Pegar; Punho por padrão."),
    T("VR Quality", "The VR preset: Low to Epic as the flat game's (screen-space reflections off: they differ between the eyes), or Quest, made for the Quest 3 / 3S standalone: lightmaps and the baked volume for the indirect light, MSAA 4x, nothing traced.", "O preset de VR: Baixo a Épico como no jogo normal (reflexos de tela desligados: eles diferem entre os olhos), ou Quest, feito para o Quest 3 / 3S autônomo: lightmaps e o volume assado para a luz indireta, MSAA 4x, nada por raio."),
    T("Foveated Rendering", "Shades the edges of each eye coarser than its middle (the lens blurs them anyway): Low, Medium, High. High cut the GPU's time of both eyes by a third in the house scene, the middle untouched.", "Sombreia as bordas de cada olho mais grosso que o meio (a lente já as desfoca): Baixa, Média, Alta. A Alta tirou um terço do tempo de GPU dos dois olhos na cena da casa, sem mexer no meio."),
    T("Dynamic Foveation", "Starts at Low and goes deeper (up to the level above) only while the GPU runs past 90% of the headset's frame, back after a calm second.", "Começa na Baixa e aprofunda (até o nível acima) só enquanto a GPU passa de 90% do quadro do headset, voltando depois de um segundo calmo."),
    T("Application SpaceWarp", "Meta's Application SpaceWarp: the game draws half the frames and the headset makes the others from motion vectors. Asked of the runtime; the motion vectors are not sent yet (notas-dev/xr.md).", "O Application SpaceWarp da Meta: o jogo desenha metade dos quadros e o headset faz os outros pelos vetores de movimento. Pedido ao runtime; os vetores de movimento ainda não são enviados (notas-dev/xr.md)."),
    T("VR Render Scale", "The eyes' resolution over the headset's recommended one: below 1 faster and softer, above 1 sharper and slower.", "A resolução dos olhos sobre a recomendada pelo headset: abaixo de 1 mais rápido e mais suave, acima de 1 mais nítido e mais lento."),
    T("Grabbable", "A VR hand's grip takes this actor: it follows the hand where it was taken; let go, it is thrown with the hand's speed (its physics again) or sits in a Grab Socket near it. Event On VR Grabbed / Released on it.", "O grip de uma mão de VR pega este ator: ele segue a mão de onde foi pego; solto, é arremessado com a velocidade da mão (a física dele volta) ou fica num Encaixe de Pegar perto. Event On VR Grabbed / Released nele."),
    T("Snap to Hand", "Held as made, its pivot in the hand and its axes the hand's (a gun by its grip, a tool), not where the hand happened to take it.", "Segurado como foi feito, o pivô na mão e os eixos os da mão (uma arma pelo cabo, uma ferramenta), não de onde a mão o pegou."),
    T("Grab Socket", "A place for grabbed things: one let go within 20 cm snaps here, in this actor's place and rotation. Required Tag: only actors with that Gameplay Tag fit (a key in its lock).", "Um lugar para coisas pegas: uma solta a até 20 cm encaixa aqui, no lugar e na rotação deste ator. Tag Exigida: só atores com aquela Gameplay Tag servem (uma chave na fechadura)."),
    T("VR Preview", "Plays this level on the VR headset (Quest Link, Air Link, SteamVR) in a window of its own like a VR preview: the unsaved changes too, the VR pawn's locomotion, hands and laser on.", "Joga este nível no headset de VR (Quest Link, Air Link, SteamVR) numa janela própria como uma prévia de VR: com as mudanças não salvas, a locomoção, as mãos e o laser do pawn VR."),
    T("Package for Meta Quest (VR)", "Makes the game into an APK for the Meta Quest standalone: the Khronos OpenXR loader, Meta's VR manifest (head tracking, the VR category, the Quest 2 / Pro / 3 / 3S), landscape, Start in VR. Install it with adb (developer mode on).", "Transforma o jogo num APK para o Meta Quest autônomo: o loader OpenXR da Khronos, o manifesto VR da Meta (rastreamento da cabeça, a categoria VR, Quest 2 / Pro / 3 / 3S), paisagem, Iniciar em VR. Instale com o adb (modo desenvolvedor ligado)."),
    T("Virtual Reality", "A new project ready for VR: a room with a table, cubes to grab and throw, a ball held by its grip, a Grab Socket, a door and a lever the laser uses, a platform to teleport onto, BP_VRPawn.", "Um projeto novo pronto para VR: uma sala com mesa, cubos para pegar e arremessar, uma bola segurada pelo cabo, um Encaixe de Pegar, uma porta e uma alavanca que o laser usa, uma plataforma para teleportar, BP_VRPawn."),
    // (Q25b) Project Settings > VR > Mixed Reality
    T("Mixed Reality (Passthrough)", "Asks the headset for mixed reality when the game starts: the passthrough (the real room through its cameras), the room of its Space Setup and the real depth. Off: pure VR, none of it asked for.", "Pede ao headset a realidade mista quando o jogo começa: o passthrough (o quarto real pelas câmeras), o quarto do Space Setup dele e a profundidade real. Desligado: VR puro, nada disso pedido."),
    T("Passthrough at Start", "The real world seen as the game starts; Set Passthrough Enabled turns it on and off while playing (a game that opens in the room and goes into VR).", "O mundo real visto quando o jogo começa; Set Passthrough Enabled liga e desliga durante o jogo (um jogo que abre no quarto e entra no VR)."),
    T("Passthrough Background", "Where the room shows: The Room puts it in the level's sky's place (everything not drawn is the real world); The Level's Sky keeps the sky, the room seen only through Passthrough Windows.", "Onde o quarto aparece: O Quarto o põe no lugar do céu do nível (tudo o que não é desenhado é o mundo real); O Céu do Nível mantém o céu, o quarto só visto pelas Passthrough Windows."),
    T("Passthrough Opacity", "How much of the real world is seen (0: black, 1: all of it): a dimmed room for a horror moment, a fade into VR.", "Quanto do mundo real aparece (0: preto, 1: todo): um quarto escurecido num momento de terror, uma transição para o VR."),
    T("Passthrough Style", "The real world's look, made by the headset: Color, Black & White, One Color (the Tint by its brightness: night vision, a hologram) or Adjusted (brightness, contrast, saturation).", "A aparência do mundo real, feita pelo headset: Cor, Preto e Branco, Uma Cor (a Cor do Passthrough pelo brilho: visão noturna, um holograma) ou Ajustado (brilho, contraste, saturação)."),
    T("Passthrough Tint", "One Color's color: the room's brightness drawn in it.", "A cor do estilo Uma Cor: o brilho do quarto desenhado nela."),
    T("Passthrough Brightness", "Adjusted's brightness, -100 to 100 (0: as the cameras see).", "O brilho do estilo Ajustado, de -100 a 100 (0: como as câmeras veem)."),
    T("Passthrough Contrast", "Adjusted's contrast (1: as the cameras see).", "O contraste do estilo Ajustado (1: como as câmeras veem)."),
    T("Passthrough Saturation", "Adjusted's saturation (0: gray, 1: as the cameras see).", "A saturação do estilo Ajustado (0: cinza, 1: como as câmeras veem)."),
    T("Passthrough Edge Color", "The real world's edges drawn in this color by the headset (alpha 0: none): a scanner, a stylized look.", "As bordas do mundo real desenhadas nesta cor pelo headset (alfa 0: nenhuma): um scanner, um visual estilizado."),
    T("Virtual Opacity", "The virtual things over the room: 1 solid, lower lets the room through them (Set Passthrough Blend fades between VR and the real world).", "As coisas virtuais sobre o quarto: 1 sólidas, menos deixa o quarto aparecer através delas (Set Passthrough Blend faz a transição entre o VR e o mundo real)."),
    T("Load the Room", "Reads the headset's Space Setup when the game starts: the floor, ceiling, walls, tables, couches, beds, windows and doors, with their labels (Event On Room Loaded runs).", "Lê o Space Setup do headset quando o jogo começa: chão, teto, paredes, mesas, sofás, camas, janelas e portas, com os rótulos (o Event On Room Loaded roda)."),
    T("Room Actors", "Each plane and piece of furniture of the room becomes an actor (MR Floor, MR Wall 2, MR Table...) that collides and is never drawn: the Characters walk on the real floor, the physics lands on the real table, Line Trace by Channel hits them.", "Cada plano e móvel do quarto vira um ator (MR Floor, MR Wall 2, MR Table...) que colide e nunca é desenhado: os Characters andam no chão real, a física cai na mesa real, o Line Trace by Channel os acerta."),
    T("Room Mesh", "The room's scanned mesh too (every real thing, not only the planes): Line Trace Real World reaches a chair, a box on the floor.", "A malha escaneada do quarto também (toda coisa real, não só os planos): o Line Trace Real World alcança uma cadeira, uma caixa no chão."),
    T("Ask for the Room Setup", "With no room scanned yet, the headset's Space Setup opens so the player scans it (Request Room Setup does it from a Blueprint).", "Sem quarto escaneado ainda, o Space Setup do headset abre para o jogador escanear (o Request Room Setup faz isso de um Blueprint)."),
    T("Align the Level to the Room", "When the room loads, the level is turned so its X runs along the room's longest wall: the level's walls where the real ones are, the collision boxes exact.", "Quando o quarto carrega, o nível gira para o X dele correr ao longo da parede mais longa do quarto: as paredes do nível onde estão as reais, as caixas de colisão exatas."),
    T("Real Windows and Doors", "The room's real windows and doors show through the virtual walls built where the real ones are.", "As janelas e portas reais do quarto aparecem através das paredes virtuais feitas onde estão as reais."),
    T("Real World Occlusion", "Real things nearer than the virtual ones hide them: the Real Depth of the headset (Quest 3 / 3S: a hand, a chair in front of a virtual ball), or the room's planes and furniture (where there is no real depth).", "Coisas reais mais perto que as virtuais as escondem: a Profundidade Real do headset (Quest 3 / 3S: uma mão, uma cadeira na frente de uma bola virtual), ou os planos e móveis do quarto (onde não há profundidade real)."),
    T("Occlusion Softness", "cm over which a real thing passes from not hiding to hiding a virtual one: a soft edge where the real depth is coarse.", "cm em que uma coisa real passa de não esconder a esconder uma virtual: uma borda suave onde a profundidade real é grossa."),
    T("Hand Removal", "The real depth leaves the player's hands out: the virtual hands drawn over the real ones instead of hidden by them.", "A profundidade real deixa as mãos do jogador de fora: as mãos virtuais desenhadas sobre as reais em vez de escondidas por elas."),
    T("Real Depth Rows From the Bottom", "Reads the headset's real depth with its rows from the bottom up (a runtime's convention): turn it on if the occlusion comes upside down.", "Lê a profundidade real do headset com as linhas de baixo para cima (a convenção de um runtime): ligue se a oclusão vier de cabeça para baixo."),
    T("Shadows on the Room", "The virtual things' shadows on the real floor, table and walls (0: none, 1: black).", "As sombras das coisas virtuais no chão, na mesa e nas paredes reais (0: nenhuma, 1: preta)."),
    T("Mixed Reality Lighting", "A Room's Light: the level's sun turned into a warm light from above, the sky light low, so the virtual things look lit by the room (and their shadows fall under them); The Level's Lights: as the level has them.", "Luz de um Quarto: o sol do nível vira uma luz quente vinda de cima, a luz do céu baixa, para as coisas virtuais parecerem iluminadas pelo quarto (e as sombras caírem embaixo delas); As Luzes do Nível: como o nível tem."),
    T("Mixed Reality Exposure", "The exposure (EV100) while the room is seen. Automatic (0): only the virtual things are metered (the room's black left out), as the flat game does; a number fixes it (a room's light: about 7).", "A exposição (EV100) enquanto o quarto aparece. Automática (0): só as coisas virtuais são medidas (o preto do quarto fica de fora), como no jogo normal; um número a fixa (luz de um quarto: uns 7)."),
    T("Hide the Level's Floor", "The level's floor planes aren't drawn while the room is seen (the real floor takes the shadows); they still collide.", "Os planos de chão do nível não são desenhados enquanto o quarto aparece (o chão real recebe as sombras); eles continuam colidindo."),
};
